import org.jsoup.Connection;
import org.jsoup.helper.DataUtil;
import org.jsoup.helper.UrlBuilder;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class UrlBuilderTest {

    @Mock
    private Connection connection;

    @Test
    public void ofUrl_isCorrect() {
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com"));
        assertEquals("http://example.com", builder.build().toString());
    }

    @Test
    public void withoutScheme_andAuthority_thenEmptyUrlIsCreated() {
        UrlBuilder builder = new UrlBuilder(new URI("/path/to/resource").toURL());
        assertNotNull(builder.build());
    }

    @Test
    public void appendKeyVal_withCorrectQueryParams_thenUpdatedUrlIsCreated() throws UnsupportedEncodingException {
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com"));
        Connection.KeyVal kv = Connection.KeyVal.of("param1", "value1");
        when(connection.query().put(kv)).thenReturn(kv);
        builder.appendKeyVal(kv);
        assertEquals("http://example.com?param1=value1", builder.build().toString());
    }

    @Test
    public void appendKeyVal_withoutExistingQueryParam_thenNewParamIsCreated() throws UnsupportedEncodingException {
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com"));
        Connection.KeyVal kv = Connection.KeyVal.of("newParam", "newValue");
        when(connection.query().put(kv)).thenReturn(kv);
        builder.appendKeyVal(kv);
        assertEquals("http://example.com?newParam=newValue", builder.build().toString());
    }

    @Test
    public void build_withNullUrl_thenUrlBuilderIsNotNull() {
        UrlBuilder builder = new UrlBuilder(null);
        assertNotNull(builder);
    }

    @Test
    public void appendKeyVal_withInvalidEncoding_thenThrowsUnsupportedEncodingException() throws UnsupportedEncodingException {
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com"));
        Connection.KeyVal kv = Connection.KeyVal.of(StringUtil.UTF_8, "value with invalid encoding");
        builder.appendKeyVal(kv);
        assertTrue(builder.build().getProtocol().equals("http") && builder.build().getHost().contains("example.com"));
    }
}
